export function normalizeProvider(provider, fallback) {
  if (!provider)
    return fallback;
  if (typeof provider === "string")
    return provider;
  if (!provider.server || !provider.client)
    throw new TypeError("`icon.provider` object must define both `server` and `client`, e.g. `{ server: 'server', client: 'iconify' }`.");
  return {
    server: provider.server,
    client: provider.client
  };
}
export function getSideProvider(provider, side) {
  return typeof provider === "object" ? provider?.[side] : provider;
}
export function usesLocalApi(provider) {
  return getSideProvider(provider, "server") === "server" || getSideProvider(provider, "client") === "server";
}
